import{_ as t,o as a,c as o,ao as s}from"./chunks/framework.CwrF1Ikc.js";const g=JSON.parse('{"title":"Comparing results","description":"","frontmatter":{},"headers":[],"relativePath":"compare.md","filePath":"compare.md","lastUpdated":null}'),i={name:"compare.md"};function r(d,e,l,n,c,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="Comparing-results" tabindex="-1">Comparing results <a class="header-anchor" href="#Comparing-results" aria-label="Permalink to &quot;Comparing results {#Comparing-results}&quot;">​</a></h1><p><a href="https://github.com/WaterLily-jl/WaterLily-Benchmarks/blob/main/compare.jl" target="_blank" rel="noreferrer"><code>compare.jl</code></a> reads the JSON files of <code>benchmark.sh</code> and prints one table per case and size, with one row per backend, WaterLily ref, Julia version and float type. <a href="./methodology">Methodology</a> explains how the columns are measured.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compare.jl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data_dir=data/benchmark</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --patterns=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tgv jelly-biotsavart&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --speedup_base=CPUx01</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sort=Backend</span></span></code></pre></div><h2 id="Choosing-the-files" tabindex="-1">Choosing the files <a class="header-anchor" href="#Choosing-the-files" aria-label="Permalink to &quot;Choosing the files {#Choosing-the-files}&quot;">​</a></h2><p>Either search a directory, or pass the files, not both:</p><ul><li><p><code>--data_dir=&lt;dir&gt;</code> (default <code>data/benchmark</code>) with <code>--patterns=&quot;&lt;p1&gt; &lt;p2&gt;&quot;</code> (space- or comma-separated, default: every case) reads the files under <code>&lt;dir&gt;</code> whose path matches <code>*&lt;pattern&gt;*</code>. A pattern is a substring, so <code>tgv</code> also matches <code>tgv-periodic</code>, and <code>--patterns=&quot;tgv*CPU&quot;</code> keeps the CPU runs of <code>tgv</code>.</p></li><li><p>JSON files as arguments, e.g. <code>julia --project compare.jl data/benchmark/*/tgv_*.json</code>.</p></li></ul><p>Files with identical tags are repetitions of one benchmark (<code>benchmark.sh -r</code>) and are merged into one row.</p><h2 id="Options" tabindex="-1">Options <a class="header-anchor" href="#Options" aria-label="Permalink to &quot;Options {#Options}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Option</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>--speedup_base=&lt;values&gt;</code></td><td style="text-align:right;">the first row</td><td style="text-align:right;">the row that <code>Speedup</code> divides by and that sets the reference rows of <code>Δ ± σ</code>, see below</td></tr><tr><td style="text-align:right;"><code>--sort=&lt;column&gt;</code></td><td style="text-align:right;">file order</td><td style="text-align:right;">sort the rows by a column, given by (the start of) its name, case-insensitive, e.g. <code>Backend</code>, <code>Mean</code>, <code>Speedup</code>, <code>Signif</code>; a column index (1 to 14, counting the hidden <code>GC</code>) also works</td></tr><tr><td style="text-align:right;"><code>--markdown</code></td><td style="text-align:right;">off</td><td style="text-align:right;">print GitHub markdown tables, as posted on <a href="./pull-requests">pull requests</a></td></tr><tr><td style="text-align:right;"><code>--gc</code></td><td style="text-align:right;">off</td><td style="text-align:right;">show the <code>GC [%]</code> column</td></tr><tr><td style="text-align:right;"><code>--plot_dir=&lt;dir&gt;</code></td><td style="text-align:right;">none</td><td style="text-align:right;">also save plots, see <a href="/WaterLily-Benchmarks/dev/compare#Plots">Plots</a></td></tr><tr><td style="text-align:right;"><code>--backend_color=&lt;scheme&gt;</code></td><td style="text-align:right;"><code>lightrainbow</code></td><td style="text-align:right;"><a href="https://docs.juliaplots.org/dev/generated/colorschemes/" target="_blank" rel="noreferrer">color scheme</a> of the plots</td></tr></tbody></table><p>In the text tables the speedup baseline row is blue and the fastest row of each backend green; in markdown they are bold and italic.</p><h2 id="Speedup-baseline" tabindex="-1">Speedup baseline <a class="header-anchor" href="#Speedup-baseline" aria-label="Permalink to &quot;Speedup baseline {#Speedup-baseline}&quot;">​</a></h2><p><code>--speedup_base</code> takes comma-separated values that a single row must all match: a backend label (<code>CPUx04</code>, <code>GPU-NVIDIA</code>), a WaterLily ref or hash (<code>master</code>, <code>v1.8.0</code>, <code>50cb584</code>), a Julia version (<code>1.11.5</code>) or a float type (<code>Float32</code>), and for a <a href="./biotsavart"><code>-bs</code> run</a> a BiotSavartBCs ref or hash. The first matching row is the baseline, e.g. <code>--speedup_base=&quot;CPUx01,master&quot;</code>. Matching is case-sensitive (<code>CPUx04</code>, not <code>cpux04</code>). If nothing matches, the error lists the rows that are available.</p><ul><li><p><code>Speedup</code> of every row is the baseline time divided by the row time, so it also compares backends.</p></li><li><p><code>Δ ± σ</code> of a row compares it with its <em>reference row</em>: the row of the same backend with the WaterLily ref, Julia version and float type of the baseline. With <code>--speedup_base=master</code>, each backend is compared with its own <code>master</code> row.</p></li></ul><p>WaterLily refs are named from the clone in <code>$WATERLILY_DIR</code>: a local branch at that commit, else a tag, else a remote branch, else the hash. Point it to an up-to-date clone when reading results from another machine.</p><h2 id="Plots" tabindex="-1">Plots <a class="header-anchor" href="#Plots" aria-label="Permalink to &quot;Plots {#Plots}&quot;">​</a></h2><p><code>--plot_dir=&lt;dir&gt;</code> saves two PDF files per case into <code>&lt;dir&gt;</code> (relative to the repository root): the cost per cell and time step, <code>&lt;case&gt;_cost_&lt;versions&gt;.pdf</code>, and the speedup, <code>&lt;case&gt;_benchmark_&lt;versions&gt;.pdf</code>. The plotting packages live in a separate environment that has to be instantiated once, see <a href="./environments">Environments</a>.</p>',16)])])}const m=t(i,[["render",r]]);export{g as __pageData,m as default};
